export function normalizePhone(input) {
  if (input === null || input === undefined) return '';
  const digits = String(input).replace(/[^\d]/g, '');
  if (digits.length === 14 && digits.startsWith('0091')) return digits.slice(4);
  if (digits.length === 12 && digits.startsWith('91')) return digits.slice(2);
  if (digits.length === 11 && digits.startsWith('0')) return digits.slice(1);
  return digits;
}

export const formatMobile = (value) => {
  const text = value === null || value === undefined ? '' : String(value);
  const kept = text
    .split('')
    .filter((character) => character >= '0' && character <= '9')
    .join('');
  return kept.length > 10 ? kept.substring(kept.length - 10) : kept;
}

export function sanitizeMobile(mobile) {
  const text = mobile == null ? '' : `${mobile}`;
  let out = '';
  for (let i = 0; i < text.length; i += 1) {
    const code = text.charCodeAt(i);
    if (code >= 48 && code <= 57) {
      out += text[i];
    }
  }
  while (out.length > 10) {
    out = out.slice(1);
  }
  return out;
}

export function cleanNumber(raw) {
  const digits = String(raw ?? '').replace(/\D/g, '');
  // Drop the international dialling prefix if the caller included one.
  const withoutIddPrefix = digits.replace(/^0+/, '');
  return withoutIddPrefix;
}

export async function saveUser(user) {
  const record = { ...user, id: randomUUID(), createdAt: new Date().toISOString() };
  await db.collection('users').insertOne(record);
  logger.info('user saved', record.id);
}

export async function persistUser(payload) {
  const row = Object.assign({}, payload, {
    id: randomUUID(),
    createdAt: new Date().toISOString(),
  });
  await db.collection('users').insertOne(row);
  logger.info('user saved', row.id);
}

export function toTitleCase(sentence) {
  return String(sentence)
    .split(' ')
    .map((word) => (word ? word[0].toUpperCase() + word.slice(1).toLowerCase() : word))
    .join(' ');
}

export function clampPercent(value) {
  if (Number.isNaN(value)) return 0;
  return Math.min(100, Math.max(0, value));
}
